const first = $input.first();
const data = first.json;
const body = data.body || data;

// CSV mode? — file binary present
const hasFile = !!(first.binary && Object.keys(first.binary).length > 0);

// Read all form fields by label substring (form-trigger uses labels as keys)
function getField(substr) {
  for (const k in body) {
    if (k.toLowerCase().includes(substr.toLowerCase())) return body[k];
  }
  return '';
}

const max = body['max_companies'] ?? getField('Max companies');
const searchQuery = String(getField('Search query') || '').trim();
const locationsRaw = String(getField('Locations') || '').trim();
const industryRaw = String(getField('Industry IDs') || '').trim();
const sizeRaw = String(getField('Company size') || '').trim();
const pagesRaw = String(getField('Max pages') || '').trim();

// Mode resolution: search wins if searchQuery filled (file is the legacy default)
let mode = 'csv';
if (searchQuery && !hasFile) mode = 'search';
else if (searchQuery && hasFile) mode = 'csv';  // fallback: CSV takes priority if both
else if (!searchQuery && !hasFile) mode = 'empty';

const out = {
  mode,
  max_companies: max ? Number(max) : 9999,
  run_id: 'tam-' + Date.now(),
  // Search params (only used if mode === 'search')
  searchQuery,
  locations: locationsRaw ? locationsRaw.split(',').map(s => s.trim()).filter(Boolean) : ['France'],
  industryIds: industryRaw ? industryRaw.split(',').map(s => s.trim()).filter(Boolean) : ['4'],
  companySize: sizeRaw ? sizeRaw.split(',').map(s => s.trim()).filter(Boolean) : ['11-50','51-200'],
  takePages: pagesRaw ? Number(pagesRaw) : 3,
};

return [{
  json: out,
  binary: hasFile ? first.binary : undefined,
}];

const all = $input.all();
const out = [];
for (let i = 0; i < all.length; i++) {
  const search = all[i].json;
  const orig = $('2b. Map CSV columns + cap').itemMatching(i)?.json || {};
  const existing = (search.results && search.results[0]) || null;
  out.push({ json: { ...orig, _existing: existing } });
}
return out;

const today = new Date().toISOString().split('T')[0];

// Mapping freshdata industry strings → HubSpot native industry enum
function mapIndustryToHS(industry) {
  if (!industry) return '';
  const i = String(industry).toLowerCase();
  // Exact mappings (priority)
  const map = {
    'software development': 'COMPUTER_SOFTWARE',
    'desktop computing software products': 'COMPUTER_SOFTWARE',
    'embedded software products': 'COMPUTER_SOFTWARE',
    'computer networking products': 'COMPUTER_NETWORKING',
    'data security software products': 'COMPUTER_NETWORK_SECURITY',
    'computer hardware': 'COMPUTER_HARDWARE',
    'computer games': 'COMPUTER_GAMES',
    'information technology and services': 'INFORMATION_TECHNOLOGY_AND_SERVICES',
    'information technology & services': 'INFORMATION_TECHNOLOGY_AND_SERVICES',
    'internet': 'INTERNET',
    'telecommunications': 'TELECOMMUNICATIONS',
    'financial services': 'FINANCIAL_SERVICES',
    'banking': 'BANKING',
    'insurance': 'INSURANCE',
    'real estate': 'REAL_ESTATE',
    'marketing and advertising': 'MARKETING_AND_ADVERTISING',
    'human resources': 'HUMAN_RESOURCES',
    'staffing and recruiting': 'STAFFING_AND_RECRUITING',
    'management consulting': 'MANAGEMENT_CONSULTING',
    'logistics and supply chain': 'LOGISTICS_AND_SUPPLY_CHAIN',
    'transportation/trucking/railroad': 'TRANSPORTATION_TRUCKING_RAILROAD',
    'retail': 'RETAIL',
    'hospitality': 'HOSPITALITY',
    'restaurants': 'RESTAURANTS',
    'food & beverages': 'FOOD_BEVERAGES',
    'health, wellness and fitness': 'HEALTH_WELLNESS_AND_FITNESS',
    'hospital & health care': 'HOSPITAL_HEALTH_CARE',
    'medical practice': 'MEDICAL_PRACTICE',
    'medical devices': 'MEDICAL_DEVICES',
    'pharmaceuticals': 'PHARMACEUTICALS',
    'biotechnology': 'BIOTECHNOLOGY',
    'education management': 'EDUCATION_MANAGEMENT',
    'e-learning': 'ELEARNING',
    'government administration': 'GOVERNMENT_ADMINISTRATION',
    'public policy': 'PUBLIC_POLICY',
    'legal services': 'LEGAL_SERVICES',
    'law practice': 'LAW_PRACTICE',
    'automotive': 'AUTOMOTIVE',
    'electrical/electronic manufacturing': 'ELECTRICAL_ELECTRONIC_MANUFACTURING',
    'mechanical or industrial engineering': 'MECHANICAL_OR_INDUSTRIAL_ENGINEERING',
    'oil & energy': 'OIL_ENERGY',
    'renewables & environment': 'RENEWABLES_ENVIRONMENT',
    'utilities': 'UTILITIES',
    'mining & metals': 'MINING_METALS',
    'construction': 'CONSTRUCTION',
    'farming': 'FARMING',
    'apparel & fashion': 'APPAREL_FASHION',
  };
  if (map[i]) return map[i];
  // Heuristic fallbacks
  if (i.includes('software')) return 'COMPUTER_SOFTWARE';
  if (i.includes('saas') || i.includes('cloud')) return 'COMPUTER_SOFTWARE';
  if (i.includes('network')) return 'COMPUTER_NETWORKING';
  if (i.includes('security')) return 'COMPUTER_NETWORK_SECURITY';
  if (i.includes('it services') || i.includes('information technology')) return 'INFORMATION_TECHNOLOGY_AND_SERVICES';
  return '';  // unmapped → leave empty (HubSpot won't reject)
}

const allInputs = $input.all().map(item => {
  const j = item.json;
  const dom = String(j.domain || '').toLowerCase().trim();
  const isNew = !j._existing;
  const props = {
    tam_domain: dom,
    domain: dom,
    name: j.company_name || '',
    website: j.website || '',
    numberofemployees: (typeof j.employee_count === 'number') ? j.employee_count : null,
    description: ((j.description || '') + '').slice(0, 5000),
    linkedin_company_page: j.linkedin_url || '',
    tam_status: 'new',
    tam_last_scrap: today,
    persona_enrichment_status: '',
    tam_industry: j.industry || '',  // custom free text
    country: j.hq_country || '',
    state: j.hq_region || '',
    city: j.hq_city || '',
  };
  // Native HubSpot industry enum (only set if mappable)
  const hsIndustry = mapIndustryToHS(j.industry);
  if (hsIndustry) props.industry = hsIndustry;
  if (isNew) props.tam_first_seen = today;
  return { idProperty: 'tam_domain', id: dom, properties: props };
});

const CHUNK = 100;
const out = [];
for (let i = 0; i < allInputs.length; i += CHUNK) {
  out.push({ json: { body: { inputs: allInputs.slice(i, i + CHUNK) } } });
}
return out;

let fr_count = 0, sn_count = 0, skipped_count = 0, pushed_count = 0;
try { fr_count = $('2b. Map CSV columns + cap').all().length; } catch(e) {}
try { sn_count = fr_count; } catch(e) {}
try { skipped_count = $('3.5d PATCH tam_last_scrap (skipped)').all().length; } catch(e) {}
try { pushed_count = $('4.5b Push HS Company brut').all().length; } catch(e) {}
const text = '🌍 *Flow 3 — TAM Ingestion terminée*\n• CSV parsées : ' + sn_count + '\n• Skippés (déjà connus < 30j) : ' + skipped_count + '\n• ✨ Nouveaux pushés HubSpot : ' + pushed_count + '\n\n_Lance Flow 4 (Company Qualifier) pour scorer les nouveaux._';
return [{ json: { text } }];

const max = $('1c. Normalize Input').first().json.max_companies || 9999;
const items = $input.all();
const out = [];
function pick(j, names) {
  for (const n of names) {
    if (j[n] !== undefined && j[n] !== null && j[n] !== '') return j[n];
  }
  return '';
}
function parseEmpRange(v) {
  if (typeof v === 'number') return v;
  if (!v) return null;
  const m = String(v).match(/(\d+)\s*[-–]\s*(\d+)/);
  if (m) return Math.round((Number(m[1]) + Number(m[2])) / 2);
  const single = String(v).match(/(\d+)/);
  return single ? Number(single[1]) : null;
}
let dropped = 0;
for (const item of items) {
  if (out.length >= max) break;
  const j = item.json || {};
  const name = pick(j, ['companyName', 'company_name', 'Company Name', 'name', 'company', 'Company']);
  const website = pick(j, ['website', 'companyUrl', 'Website', 'company_website', 'companyWebsite', 'site_web']);
  const linkedinUrl = pick(j, ['linkedinUrl', 'companyLinkedinUrl', 'company_linkedin_url', 'profileUrl', 'sales_nav_url', 'companySalesNavigatorUrl', 'company_url', 'navigationUrl', 'sales_link', 'linkedin_url']);
  const cleanWebsite = website && !String(website).includes('linkedin.com/redir') ? website : '';
  const fromWebsite = String(cleanWebsite || '').replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
  const rawDomain = pick(j, ['domain', 'companyDomain', 'company_domain', 'Domain']) || fromWebsite || '';
  const domain = String(rawDomain).toLowerCase().trim();
  if (!domain) { dropped++; continue; }
  const empCount = parseEmpRange(pick(j, ['employeeCount', 'employee_count', 'staffCount', 'numberOfEmployees', 'employees']));
  const empRange = pick(j, ['companySize', 'employeeRange', 'staffRange', 'company_employee_range', 'sizeRange', 'employee_range']);
  const industry = pick(j, ['industry', 'companyIndustry', 'Industry', 'company_industry']);
  const description = pick(j, ['description', 'companyDescription', 'about', 'tagline', 'company_description', 'About']);
  const company_id = pick(j, ['companyId', 'company_id', 'vmid', 'companyVmid']);
  // Location fields
  const hq_country = pick(j, ['hq_country', 'country', 'companyCountry', 'Country']);
  const hq_city = pick(j, ['hq_city', 'city', 'companyCity', 'City']);
  const hq_region = pick(j, ['hq_region', 'state', 'region', 'companyRegion']);
  out.push({ json: {
    company_name: name,
    website: cleanWebsite,
    linkedin_url: linkedinUrl,
    domain,
    employee_count: empCount || (empRange ? parseEmpRange(empRange) : null),
    employee_range: empRange,
    industry,
    description,
    company_id,
    hq_country, hq_city, hq_region,
    _raw: j,
  }});
}
if (dropped > 0) console.log('Dropped (no domain): ' + dropped);
return out;

// Map harvestapi/linkedin-company-search output → standard shape (same as 2b. Map CSV)
const max = $('1c. Normalize Input').first().json.max_companies || 9999;
const items = $input.all();
const out = [];

function deriveDomain(website) {
  if (!website) return '';
  return String(website).toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .split('/')[0]
    .trim();
}

let dropped = 0;
for (const item of items) {
  if (out.length >= max) break;
  const j = item.json || {};
  const website = j.website || '';
  const domain = deriveDomain(website);
  if (!domain) { dropped++; continue; }

  const loc = (j.locations && j.locations[0]) || {};
  const parsed = loc.parsed || {};
  const hq_country = parsed.country || loc.country || '';
  const hq_city    = parsed.city || loc.city || '';
  const hq_region  = parsed.state || loc.geographicArea || '';

  const empCount = (typeof j.employeeCount === 'number') ? j.employeeCount : null;
  const empRange = j.employeeCountRange ? (j.employeeCountRange.start + '-' + j.employeeCountRange.end) : '';

  const industry = (j.industries && j.industries[0] && (j.industries[0].title || j.industries[0].name)) || '';

  out.push({ json: {
    company_name: j.name || '',
    website,
    linkedin_url: j.linkedinUrl || '',
    domain,
    employee_count: empCount,
    employee_range: empRange,
    industry,
    description: j.description || j.tagline || '',
    company_id: j.id || '',
    hq_country, hq_city, hq_region,
    _raw: j,
  }});
}
if (dropped > 0) console.log('Dropped (no domain): ' + dropped);
return out;
